learn=[('Separate three testing levels', 'Unit tests call our graders and hooks without a model. Integration checks one real query and its wiring. Evals repeat realistic tasks and measure outcomes.'), ('Version cases and fixtures', 'Each case declares a fixed prompt, optional JSON schema, expected outcome and grader. Every real run copies the versioned fixture into a new temporary workspace.'), ('Grade facts and side effects', 'Validate native structured output against actual expected fields. Independently run trusted fixture tests after validating all permitted source changes. A fluent success message is not a passing grade.'), ('Repeat and report', 'Repeated runs use fresh workspaces. Inspect per-case pass rate, estimated cost, turns and a Wilson interval. Three classroom samples cannot establish production reliability.'), ('Keep failures visible', 'Negative controls intentionally fail: an incorrect expected count, an unchanged buggy fixture, a one-turn run and a suite with a failing case. Preserve native results and failed grades.'), ('Gate changes with evidence', 'Require each case to reach the 80% observed pass threshold. Keep missing cost fields unknown, retain a JSONL record per run and compare reports with model, prompt and fixture provenance.')]
labels=[('integration', 'Integration: a real Read and hook'), ('structured', 'Structured output: grade the facts'), ('wrongexpected', 'Negative control: incorrect expectation'), ('fix', 'Fix average([]) and run trusted tests'), ('unchanged', 'Negative control: unchanged buggy fixture'), ('repeated', 'Repeat the JSON case three times'), ('suite', 'Suite: wiring, JSON and bug fix'), ('turnlimit', 'Preserve a real one-turn failure'), ('gate', 'Fail the case-level 80% gate')]
runsteps=[('Prerequisites', 'Install Node.js 24+ and have API credit for your selected model. Windows may need Git Bash. The pinned SDK supplies its runtime. No Docker, database, GitHub token or Managed Agents IDs are needed.', 'node --version\nnpm --version'), ('Install and create the private .env', 'From presentations use the cd shown. In a standalone clone skip that line. Preserve any existing .env, then enter your key privately. Shell variables take precedence; use the same shell to start the app.', 'cd .\\agent-sdk\\lesson56-testing-evals\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the web lab', 'Keep the terminal open. Explore the five pages, choose a fixed experiment, run it and inspect actual native results, hook observations, grades and reports. Expected failing controls exit 1.', 'npm start\n# http://127.0.0.1:3156'), ('Run deterministic unit tests', 'These tests verify graders, reporting, hooks, fixture isolation and startup without a model call. The fixture test intentionally fails before the known fix and passes afterward.', 'npm test'), ('Run live integration and evals', 'Integration makes one real SDK query. Repeated makes three independent structured-output runs. Suite runs three different cases. Each copy is removed after grading; evidence stays in the ignored runtime folder.', 'npm run pipeline -- integration\nnpm run pipeline -- repeated\nnpm run eval'), ('Inspect deliberate failures and configure CI', 'Wrongexpected supplies an intentionally incorrect expected count. Unchanged keeps the bug. Turnlimit captures the native limit result. Gate includes a passing integration case and failing fixture case. The repository runs source checks without API secrets; its manual evaluation workflow requires a privately configured ANTHROPIC_API_KEY repository secret. No nightly schedule is enabled.', 'npm run pipeline -- wrongexpected\nnpm run pipeline -- unchanged\nnpm run pipeline -- turnlimit\nnpm run pipeline -- gate\n$LASTEXITCODE\n# Evidence: .runtime/runs/<suite-id>/runs.jsonl and evidence.json')]
specs=[('Choose a bounded experiment', 'src/protocol.ts', 'if (', 'Validate a fixed mode. Browser input cannot supply shell commands, filesystem paths, prompts or unlimited repetition counts.', 0, 1, 7), ('Declare cases and expected outcomes', 'src/cases.ts', 'export const CASES', 'A case owns its prompt, grading kind, expected values and edit policy. Wrongexpected is a labelled negative control; its intentionally bad expectation is not a model hallucination.', 1, 1, 9), ('Plan independent repetitions', 'src/cases.ts', 'export function plan', 'Repeated runs the same JSON case three times. Suite covers three different cases; Gate deliberately includes a failing outcome. One observed success is not a reliability claim.', 1, 1, 8), ('Copy a fresh versioned fixture', 'src/workspace.ts', 'await cp(', 'Copy the trusted fixture for every run and isolate the SDK home and config. Empty settings and temporary paths reduce shared state; they are not operating-system isolation or deterministic inference.', 1, 3, 7), ('Configure the real SDK evaluation', 'src/runner.ts', 'const options: Options', 'Use the selected model, empty setting sources, explicit tools, dontAsk and finite limits. The model is fixed within a suite. Fixture graders execute locally, separately from the model.', 1, 2, 10), ('Constrain reads and exact edits', 'src/policy.ts', 'const base =', 'Resolve real paths before allowing known fixture reads. Fix mode admits only the reviewed average-empty-input change. The agent has no Bash or Write tool.', 2, 3, 10), ('Collect actual native results', 'src/runner.ts', 'const run = query', 'Consume the actual SDK stream and preserve its terminal result, requested tools and formatted text. A limit result remains a failure, even if a partial answer exists.', 2, 1, 10), ('Run independent trusted tests', 'src/runner.ts', 'if (c.grade === "tests"', 'Verify fixture contents first, remove the API key from the host test environment, then execute actual Node tests. Unchanged preserves the bug and must fail this outcome check.', 1, 4, 10), ('Grade output facts, not prose', 'src/grader.ts', 'const parsed =', 'Parse the native structured_output with Zod, then compare project and count to the case expectation. Valid JSON shape is separate from factual correctness. Never grade by exact answer wording.', 1, 4, 9), ('Retain each completed run', 'src/job.ts', 'const run = await runCase', 'Append the actual graded record to JSONL immediately. Reports retain model, SDK, fixture and prompt provenance. Partial suites cannot pass the final gate.', 1, 1, 8), ('Aggregate rates, cost and turns', 'src/report.ts', 'const costs =', 'Compute measured averages from native result fields and retain measurement coverage. Missing metrics remain unknown. Wilson intervals show the uncertainty of tiny repeated samples.', 1, 4, 10), ('Gate every case independently', 'src/report.ts', 'const passed = groups.every', 'Require every case to reach the observed 80% threshold. A passing easy case cannot hide a failing case behind an overall average. Thresholds express application policy, not statistical proof.', 4, 1, 10), ('Observe the real worker exit', 'src/agent.ts', 'child.once("close"', 'The parent observes the actual operating-system process close event and compares the exit code with the report. The UI shows both native outcomes and the case-level gate decision.', 1, 0, 6)]
reference=[('What is real', 'Integration, Structured, Fix, Repeated and Suite call the real Agent SDK. Negative controls also make real queries. Browser recordings are actual live runs; no canned response replaces model output.'), ('Versioned classroom task', 'The fixture has a three-item catalog and a tiny average function with an empty-input bug. Fix may change only its return expression. The agent has Read/Edit; the host runs the trusted tests independently after exact content checks.'), ('Integration is not an eval score', 'Integration grades a real Read request, hook observation and successful native result. It checks wiring, not the correctness of arbitrary prose. Structured and fixture-test cases grade declared facts or behavior.'), ('Negative controls and incomplete runs', 'Wrongexpected deliberately expects count 99 while the fixture contains 3. Unchanged asks for read-only diagnosis and leaves a failing test. These controls demonstrate graders; they do not measure an agent failing a fair fix task. Turnlimit preserves an actual incomplete SDK result.'), ('Repeated samples and uncertainty', 'Repeated uses three genuine fresh runs for a quick teaching demonstration. The report includes a 95% Wilson interval for each observed proportion. Such a small sample cannot establish production reliability; use representative held-out cases and larger repeated samples.'), ('Costs, turns and missing fields', 'Native total_cost_usd values are SDK estimates. Averages include only observed numeric fields and show coverage. Missing fields are null rather than invented free runs. The per-run $0.35 estimate threshold may overshoot and is not a hard invoice cap.'), ('Case-level CI policy', 'The gate is per case at 80%, not a pooled average. Every planned run must finish. Expected failing modes exit 1. The public workflow runs only deterministic source checks automatically; real hosted evals are manual and need your repository secret.'), ('Model comparisons and judge grading', 'Reports include the selected model, prompt hash, fixture hash and grader version. Save reports for both configurations before comparing quality and cost. This app uses deterministic outcome graders; a model judge for fuzzy quality is a future exercise, not a hidden implemented score.'), ('Primary references', 'Agent SDK structured output: https://code.claude.com/docs/en/agent-sdk/structured-outputs ; cost fields: https://code.claude.com/docs/en/agent-sdk/cost-tracking ; Node tests: https://nodejs.org/api/test.html')]

env="ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3156\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe"
select=''.join(f'<option value="{m}">{escape(t)}</option>' for m,t in labels)
body='<section class="panel" id="controls"><h2>Run an evaluation experiment</h2><p id="configuration">Checking configuration...</p><label for="mode">Experiment</label><select id="mode">'+select+'</select><div class="actions"><button class="primary" id="run" disabled>Run real evaluation →</button><button id="download">Download actual evidence</button></div><p class="note">Each run copies a trusted fixture into a fresh workspace. Some experiments intentionally fail. Repeated and Suite make three real queries. No agent shell commands are available.</p><p id="status" role="status">Choose an experiment.</p></section>'
body+='<div class="grid"><article class="card"><h3>Actual worker exit</h3><p id="span-count">Pending</p></article><article class="card"><h3>Native results</h3><p id="metric-count">0</p></article><article class="card"><h3>Actual tool requests</h3><p id="log-count">0</p></article></div>'
body+='<div class="workspace"><section class="panel" id="chat-panel"><h2>Actual formatted agent responses</h2><div id="conversation" class="markdown-body"></div></section><section class="panel" id="option-panel"><h2>Actual SDK configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section></div>'
def panel(id,title,code):return f'<section class="step" id="{id}"><h2>{title}</h2><pre class="json-view"><code id="{code}" class="language-json">{{}}</code></pre></section>'
body+=panel('process-panel','Actual process exit and case-level report','process')
body+='<section class="step" id="artifact-panel"><h2>Fixture changes and independent outcome grades</h2><pre><code id="diff" class="language-diff">Waiting for a real evaluation.</code></pre><pre class="json-view"><code id="host-checks" class="language-json">{}</code></pre></section>'
def tablepanel(id,title,heads,target,extra=''):
 return f'<section class="step" id="{id}"><h2>{title}</h2>'+extra+'<div class="table"><table><thead><tr>'+''.join('<th>'+h+'</th>'for h in heads)+f'</tr></thead><tbody id="{target}"></tbody></table></div></section>'
body+=tablepanel('trace-panel','Actual fixture hook decisions',['Tool','Decision','Input'],'trace-history')
body+=tablepanel('metric-panel','Observed pass rates, cost and turns',['Case','Passed / runs','Measurements and uncertainty'],'metric-history')
body+=tablepanel('model-panel','Actual harness observations',['Stage','Evidence'],'log-history','<label for="user-filter">Filter by exact observation kind</label><input id="user-filter" placeholder="configuration">')
for id,title,code in [('results-panel','Actual final native result','native-result'),('storage-panel','Fixture isolation and provenance','storage'),('diagnostic-panel','Incomplete runs and grader reasons','diagnostics'),('evidence-panel','All actual evaluation evidence','evidence'),('specialists-panel','All actual observations','telemetry'),('requests-panel','Native tool requests','requests')]:body+=panel(id,title,code)
document('/','Test agents. <em>Measure outcomes.</em>','Unit tests, real SDK integration and repeated evaluations with independent graders.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Separate deterministic source tests from real model evaluations.',cards(learn)+actions(('/','Application lab'),('/run.html','How to run')))
run=''
for i,(title,text,code) in enumerate(runsteps,1):run+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{escape(title)}</h2><p>{escape(text)}</p>'+snippet(code,'powershell')+(snippet(env,'ini')if i==2 else '')+'</section>'
document('/run.html','Configure and <em>run the app.</em>','Preserve your private .env. Start locally, then inspect real grades and reports.',run)
steps=[];arrows=[];lanes=['Student UI','Eval harness','Agent SDK','Fixture copy','Outcome grader']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='yaml' if source.endswith('.yml') else 'javascript' if source.endswith('.js') else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 56 · Isolate → run → grade → report</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{max(40,min(min(x1,x2)+10,1700-len(label)*13))}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'],s['language'])+'</section>'

document('/architecture.html','Architecture and <em>UML workflow.</em>','Every one of the thirteen steps includes matching coloured source code.','<p class="note">The harness loops over cases and repetitions. Each query uses a fresh fixture. Deterministic graders check structured facts and trusted tests; the report determines the actual worker exit. These are logical participants inside the local app, not separately deployed services.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen-step evaluation harness sequence"></div>'+walk)
document('/walkthrough.html','How the app <em>was built.</em>','Read the actual case, runner, grader and report code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 56 · Testing and evaluating agents\n\nFive student pages, thirteen source-linked UML steps and nine real evaluation experiments.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n'for a,b in learn)
